const readline = require('readline');
const rl = readline.createInterface({ input: process.stdin, terminal: false });
let inputLine = '';
rl.on('line', (line) => { inputLine += line.trim(); });
rl.on('close', () => {
    let x = BigInt(inputLine);
    let mod360 = 360n;
    let r = ((-x) % mod360 + mod360) % mod360;
    let rNum = Number(r);
    let bestK = 0;
    let bestDev = Infinity;
    for (let k = 0; k < 4; k++) {
        let total = (rNum + 90 * k) % 360;
        let dev = Math.min(total, 360 - total);
        if (dev < bestDev) {
            bestDev = dev;
            bestK = k;
        }
    }
    console.log(bestK);
});
